"use client"

import { useState } from 'react';
import { ArrowRightIcon, BanknotesIcon, CalendarIcon } from '@heroicons/react/24/outline';
import Link from 'next/link';

export default function LoanApplication() {
  const [amount, setAmount] = useState('');
  const [term, setTerm] = useState('');

  const handleSubmit = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    console.log('Loan Amount:', amount, 'Term:', term);
  };

  return (
    <div className="flex flex-col items-center justify-center min-h-screen bg-gray-100 p-6">
      <h1 className="text-3xl font-bold mb-6">Apply for a Loan</h1>
      <form onSubmit={handleSubmit} className="bg-white shadow-md rounded-lg p-8 w-full max-w-md">
        <div className="mb-4">
          <label htmlFor="amount" className="flex items-center text-sm font-medium text-gray-700">
            <BanknotesIcon className="h-5 w-5 mr-2" />
            Loan Amount
          </label>
          <input
            type="number"
            id="amount"
            value={amount}
            onChange={(e) => setAmount(e.target.value)}
            className="mt-1 block w-full border border-gray-300 rounded-md p-2"
            required
          />
        </div>
        <div className="mb-4">
          <label htmlFor="term" className="flex items-center text-sm font-medium text-gray-700">
            <CalendarIcon className="h-5 w-5 mr-2" />
            Loan Term (months)
          </label>
          <input
            type="number"
            id="term"
            value={term}
            onChange={(e) => setTerm(e.target.value)}
            className="mt-1 block w-full border border-gray-300 rounded-md p-2"
            required
          />
        </div>
        <button
          type="submit"
          className="flex items-center gap-2 rounded-lg bg-blue-500 px-4 py-2 text-white transition-colors hover:bg-blue-400"
        >
          Submit Application <ArrowRightIcon className="w-5" />
        </button>
      </form>
      <Link href="/dashboard" className="mt-4 text-blue-500">
        Back to Dashboard
      </Link>
    </div>
  );
}